var Q14 = [
{n:1, q:'Los delitos contra el patrimonio y el orden socioeconómico están tipificados:', o:{a:'En el Título XIII, del Libro II del Código Penal.',b:'En el Título XII, del Libro II del Código Penal.',c:'En el Título XI, del Libro II del Código Penal.',d:'En el Título X, del Libro II del Código Penal.'}, correct:'a', why:{a:'Los delitos contra el patrimonio y el orden socioeconómico están en el Título XIII del Libro II del CP.'}},
{n:2, q:'El Título XIII, del Libro II del Código Penal, con el epígrafe "delitos contra el patrimonio y el orden socioeconómico", se estructura en:', o:{a:'Dieciocho capítulos.',b:'Catorce capítulos.',c:'Doce capítulos.',d:'Diez capítulos.'}, correct:'b', why:{b:'El Título XIII del Libro II del CP se estructura en catorce capítulos.'}},
{n:3, q:'El Capítulo I, del Título XIII, del Libro II del Código Penal se denomina:', o:{a:'De los robos.',b:'De la extorsión.',c:'Del Robo y hurto de uso de vehículos.',d:'De los hurtos.'}, correct:'d', why:{d:'El Capítulo I del Título XIII del CP se denomina "De los hurtos" (arts.234-235).'}},
{n:4, q:'El Capítulo II, del Título XIII, del Libro II del Código Penal se denomina:', o:{a:'De los robos.',b:'De la extorsión.',c:'Del Robo y hurto de uso de vehículos.',d:'De los hurtos.'}, correct:'a', why:{a:'El Capítulo II del Título XIII del CP se denomina "De los robos" (arts.237-242).'}},
{n:5, q:'El Capítulo III, del Título XIII, del Libro II del Código Penal se denomina:', o:{a:'De los robos.',b:'De la extorsión.',c:'Del Robo y hurto de uso de vehículos.',d:'De los hurtos.'}, correct:'b', why:{b:'El Capítulo III del Título XIII del CP se denomina "De la extorsión" (art.243).'}},
{n:6, q:'El Capítulo IV, del Título XIII, del Libro II del Código Penal se denomina:', o:{a:'De los robos.',b:'De la extorsión.',c:'Del Robo y hurto de uso de vehículos.',d:'De los hurtos.'}, correct:'c', why:{c:'El Capítulo IV del Título XIII del CP se denomina "Del robo y hurto de uso de vehículos" (art.244).'}},
{n:7, q:'El Capítulo V, del Título XIII, del Libro II del Código Penal se denomina:', o:{a:'De la usurpación.',b:'De las defraudaciones.',c:'De los daños.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'El Capítulo V del Título XIII del CP se denomina "De la usurpación" (arts.245-247).'}},
{n:8, q:'El Capítulo VI, del Título XIII, del Libro II del Código Penal se denomina:', o:{a:'De la usurpación.',b:'De las defraudaciones.',c:'De los daños.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'b', why:{b:'El Capítulo VI del Título XIII del CP se denomina "De las defraudaciones" (arts.248-262 bis).'}},
{n:9, q:'El Capítulo IX, del Título XIII, del Libro II del Código Penal se denomina:', o:{a:'De la usurpación.',b:'De las defraudaciones.',c:'De los daños.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'El Capítulo IX del Título XIII del CP se denomina "De los daños" (arts.263-267).'}},
{n:10, q:'El Capítulo I, del Título XIII, del Libro II del Código Penal, dedicado a los hurtos, comprende los artículos...', o:{a:'248 a 251 bis.',b:'234 a 236.',c:'245 a 247.',d:'263 a 267.'}, correct:'b', why:{b:'El Capítulo I "De los hurtos" comprende los artículos 234 a 236 del CP.'}},
{n:11, q:'El Capítulo II, del Título XIII, del Libro II del Código Penal, dedicado a los robos, comprende los artículos...', o:{a:'248 a 251 bis.',b:'234 a 236.',c:'245 a 247.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'El Capítulo II "De los robos" comprende los artículos 237 a 242 del CP, lo cual no coincide con ninguna de las opciones.'}},
{n:12, q:'El Capítulo III, del Título XIII, del Libro II del Código Penal, dedicado a la extorsión, comprende los artículos...', o:{a:'248 a 251 bis.',b:'234 a 236.',c:'245 a 247.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'El Capítulo III "De la extorsión" comprende el artículo 243 del CP, lo cual no coincide con ninguna opción.'}},
{n:13, q:'El Capítulo IV, del Título XIII, del Libro II del Código Penal, dedicado al robo y hurto de uso de vehículos, comprende los artículos...', o:{a:'248 a 251 bis.',b:'234 a 236.',c:'245 a 247.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'d', why:{d:'El Capítulo IV "Del robo y hurto de uso de vehículos" comprende el artículo 244 del CP, lo cual no coincide con ninguna opción.'}},
{n:14, q:'El Capítulo IX, del Título XIII, del Libro II del Código Penal, dedicado a los daños, comprende los artículos...', o:{a:'263 a 267.',b:'235 a 267 bis.',c:'266 a 269.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'El Capítulo IX "De los daños" comprende los artículos 263 a 267 del CP.'}},
{n:15, q:'De los siguientes, indique aquel que no está considerado delito contra el patrimonio y el orden socioeconómico en el vigente Código Penal:', o:{a:'La extorsión.',b:'La usurpación.',c:'La malversación.',d:'La estafa.'}, correct:'c', why:{c:'La malversación es un delito contra la Administración Pública (Título XIX del Libro II), no un delito contra el patrimonio del Título XIII.'}},
{n:16, q:'De los siguientes, indique aquel que no está considerado delito contra el patrimonio y el orden socioeconómico en el vigente Código Penal:', o:{a:'La administración desleal.',b:'El cohecho.',c:'La apropiación indebida.',d:'La receptación.'}, correct:'b', why:{b:'El cohecho es un delito contra la Administración Pública (Título XIX), no un delito patrimonial del Título XIII.'}},
{n:17, q:'De los siguientes, indique aquel que no está considerado delito contra el patrimonio y el orden socioeconómico en el vigente Código Penal:', o:{a:'La defraudación de fluido eléctrico.',b:'Las exacciones ilegales.',c:'La frustración en la ejecución.',d:'El blanqueo de capitales.'}, correct:'b', why:{b:'Las exacciones ilegales son un delito de los funcionarios públicos (Título XIX), no del Título XIII contra el patrimonio.'}},
{n:18, q:'De los siguientes, indique aquel que no está considerado delito contra el patrimonio y el orden socioeconómico en el vigente Código Penal:', o:{a:'El tráfico de influencias.',b:'La alteración de precios en concursos y subastas públicas.',c:'La sustracción de cosa propia a su utilidad social o cultural.',d:'El blanqueo de capitales.'}, correct:'a', why:{a:'El tráfico de influencias es delito contra la Administración Pública (Título XIX), no contra el patrimonio.'}},
{n:19, q:'Con respecto al delito de hurto del artículo 234 del Código Penal, indique la respuesta incorrecta:', o:{a:'La conducta objeto de sanción penal consiste en tomar cosas muebles ajenas, sin la voluntad de su dueño.',b:'La pena a imponer por este delito es la de prisión de 6 a 18 meses.',c:'Para que exista delito es necesario que exista ánimo de lucro.',d:'Solo constituye delito cuando la cuantía de lo sustraído supera los 400 euros.'}, correct:'d', why:{d:'La opción d es incorrecta: el art.234.1 CP castiga el hurto cuando la cuantía de lo sustraído supera los 400 euros, pero el art.234.2 CP también castiga como delito leve el hurto cuando no supera esa cuantía si concurren las circunstancias del art.235.'}},
{n:20, q:'De conformidad con lo dispuesto en el artículo 234.2 del Código Penal, se impondrá una pena de multa de uno a tres meses cuando...', o:{a:'Concurra alguna de las circunstancias del artículo 235 CP.',b:'La cuantía de lo sustraído no exceda de 400 euros.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.234.2 CP: se impone multa de 1 a 3 meses cuando la cuantía no excede 400 euros (b) y no concurren las circunstancias del art.235 (a, que permite pena superior).'}},
{n:21, q:'De conformidad con lo dispuesto en el artículo 234.2 del Código Penal, si la cuantía de lo sustraído no excediese de 400 euros, pero concurre alguna de las circunstancias del artículo 235 CP...', o:{a:'Se impone la pena superior en grado.',b:'Se impone la pena en su mitad superior.',c:'Se impone la pena de prisión de uno a tres años.',d:'Se impone la pena de multa de uno a tres meses.'}, correct:'b', why:{b:'Art.234.2 CP: si la cuantía no excede de 400 euros pero concurre alguna circunstancia del art.235, se impone la pena en su mitad superior.'}},
{n:22, q:'De conformidad con lo dispuesto en el artículo 234.2 del Código Penal, cuando el culpable de un delito leve de hurto hubiera sido condenado ejecutoriamente al menos por tres delitos comprendidos en este Título, aunque sean de carácter leve, siempre que sean de la misma naturaleza y que el montante acumulado de las infracciones sea superior a 400 €, y que no concurra ninguna de las circunstancias del artículo 235 CP, se impondrá la pena de...', o:{a:'Prisión de uno a tres años.',b:'Prisión de seis a dieciocho meses.',c:'Multa de 1 a 3 meses.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.234.2 CP: en el supuesto de reiteración (tres condenas o más del mismo Título) con montante acumulado >400€, se impone prisión de 6 meses a 18 meses.'}},
{n:23, q:'Si al cometer el delito de hurto del artículo 234 (apartados 1 y 2) del Código Penal, se hubieran neutralizado, eliminado o inutilizado, por cualquier medio, los dispositivos de alarma o seguridad instalados en las cosas sustraídas:', o:{a:'Se castigará el hecho como delito de robo con fuerza del artículo 240 del Código Penal.',b:'Se impondrá la pena superior en uno o dos grados.',c:'Se impondrán las penas establecidas para cada caso, en su mitad superior.',d:'Se impondrán las penas de multa de 1 a 3 meses y la de trabajos en beneficio de la comunidad de 1 a 30 días.'}, correct:'c', why:{c:'Art.234.3 CP: si se neutralizan dispositivos de alarma en el hurto, se imponen las penas en su mitad superior.'}},
{n:24, q:'Cuando concurre alguna de las circunstancias previstas en el artículo 235 del Código Penal, el delito de hurto se castiga con la pena de prisión de 1 a 3 años:', o:{a:'Siempre que el valor de lo sustraído exceda de los 400 euros.',b:'Con independencia de que la cuantía de los sustraído supere o no los 400 euros.',c:'Cuando en la comisión del hecho se hubieran neutralizado, eliminado o inutilizado, por cualquier medio, los dispositivos de alarma o seguridad instalados en las cosas sustraídas.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.235 CP: la pena de prisión de 1 a 3 años se aplica cuando concurre alguna circunstancia agravante, con independencia de la cuantía sustraída.'}},
{n:25, q:'En el artículo 235 del Código Penal se castiga el delito de hurto con la pena de prisión de 1 a 3 años:', o:{a:'Cuando se utilice a menores de 16 años para la comisión del delito.',b:'Cuando se cometa en casa habitada, edificio o local abiertos al público, o en cualquiera de sus dependencias.',c:'Cuando en la comisión del hecho se hubieran neutralizado, eliminado o inutilizado, por cualquier medio, los dispositivos de alarma o seguridad instalados en las cosas sustraídas.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.235.1.2ª CP: el hurto en casa habitada, edificio o local abierto al público se castiga con prisión de 1 a 3 años.'}},
{n:26, q:'En el artículo 235 del Código Penal se castiga el delito de hurto con la pena de prisión de 1 a 3 años:', o:{a:'Cuando se ponga a la víctima o a su familia en grave situación económica.',b:'Cuando hubiere mediado intimidación.',c:'Cuando para cometer el delito se hubiere hecho uso de llaves falsas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Art.235.1.5ª CP: el hurto que ponga a la víctima o su familia en grave situación económica se castiga con prisión de 1 a 3 años.'}},
{n:27, q:'En el artículo 235 del Código Penal se castiga el delito de hurto con la pena de prisión de 1 a 3 años:', o:{a:'Cuando se sustraigan cosas de valor histórico, artístico, cultural o científico.',b:'Cuando se trate de cosas de primera necesidad y se cause una situación de desabastecimiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.235.1.3ª y 4ª CP: tanto el hurto de bienes de valor cultural (a) como el que causa desabastecimiento (b) se castigan con prisión de 1 a 3 años.'}},
{n:28, q:'En el artículo 235 del Código Penal se castiga el delito de hurto con la pena de prisión de 1 a 3 años:', o:{a:'Cuando hubiese mediado escalamiento.',b:'Cuando revista especial gravedad atendiendo al valor de los efectos sustraídos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.235.1.7ª y 8ª CP: el escalamiento (a) y la especial gravedad por el valor de lo sustraído (b) son ambas circunstancias agravantes del hurto.'}},
{n:29, q:'En el artículo 235 del Código Penal se castiga el delito de hurto con la pena de prisión de 1 a 3 años:', o:{a:'Cuando se trate de conducciones, cableado, equipos o componentes de infraestructuras de suministro eléctrico o de los servicios de telecomunicaciones, y se causare un quebranto grave a los mismos.',b:'Cuando se haya realizado abusando de las circunstancias personales de la víctima o de su situación de desamparo.',c:'Cuando se produjeran perjuicios de especial consideración.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.235.1 CP: todas esas circunstancias (infraestructuras críticas, abuso de situación de desamparo y perjuicios especiales) son agravantes del hurto.'}},
{n:30, q:'En el artículo 235 del Código Penal se castiga el delito de hurto con la pena de prisión de 1 a 3 años:', o:{a:'Cuando fuere cometido por autoridad, agente de la misma o funcionario público en el ejercicio de sus funciones.',b:'Cuando se trate de productos agrarios o ganaderos, o de los instrumentos o medios que se utilizan para su obtención, siempre que el delito se cometa en explotaciones agrícolas o ganaderas y se cause un perjuicio grave a las mismas.',c:'Cuando en la comisión del hecho se hubieran neutralizado, eliminado o inutilizado, por cualquier medio, los dispositivos de alarma o seguridad instalados en las cosas sustraídas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.235.1 CP: autoridad/funcionario (a), productos agrarios en explotaciones (b) y neutralización de alarmas (c) son todas circunstancias agravantes del hurto.'}},
{n:31, q:'En el artículo 235 del Código Penal se castiga el delito de hurto con la pena de prisión de 1 a 3 años:', o:{a:'Cuando se trate de cosas destinadas a la prestación de servicios de interés general y se cause un quebranto grave a los mismos.',b:'Cuando se haya realizado aprovechando la producción de un accidente o la existencia de un riesgo o peligro general para la comunidad que haya facilitado la defensa del ofendido o facilitado la comisión impune del delito.',c:'Cuando al delinquir el culpable hubiera sido condenado ejecutoriamente al menos por tres delitos contra el patrimonio y orden socioeconómico, siempre que sean de la misma naturaleza.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.235.1 CP: servicios de interés general (a), aprovechamiento de accidente/riesgo (b) y reiteración delictiva (c) son agravantes del hurto.'}},
{n:32, q:'En el artículo 235 del Código Penal se castiga el delito de hurto con la pena de prisión de 1 a 3 años:', o:{a:'Cuando la víctima fuere menor de edad o persona con discapacidad necesitada de especial protección.',b:'Cuando se emplearen medios, métodos, modos o formas que aseguren la impunidad del delito o debiliten la defensa que pudiera realizar el ofendido.',c:'Cuando el culpable o culpables participen en los hechos como miembros de una organización o grupo criminal que se dedique a la comisión de delitos comprendidos en el Título XIII del Libro II del Código Penal, siempre que sean de la misma naturaleza.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.235.1 CP: víctima menor/discapacitada (a), medios que aseguran impunidad (b) y organización criminal (c) son agravantes del hurto.'}},
{n:33, q:'Cuando en un delito de hurto concurrieren dos o más de las circunstancias previstas en el artículo 235 del Código Penal:', o:{a:'Se castigará el hecho como delito de robo con fuerza del artículo 240 del Código Penal.',b:'Se impondrá la pena superior en uno o dos grados.',c:'Se impondrá la pena de prisión de 1 a 3 años, en su mitad superior.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.235.2 CP: cuando concurren dos o más circunstancias del art.235, se impone la pena en su mitad superior.'}},
{n:34, q:'En el artículo 236 del Código Penal se castiga la sustracción de una cosa propia, siempre y cuando:', o:{a:'El que la sustraiga sea su dueño o actúe con el consentimiento de éste.',b:'La cosa objeto de sustracción esté legítimamente en poder de otro.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.236 CP: se castiga la sustracción de cosa propia cuando está legítimamente en poder de otro (poseedor legítimo).'}},
{n:35, q:'En el artículo 236 del Código Penal se castiga la sustracción de una cosa propia, siempre y cuando:', o:{a:'Se trate de una cosa mueble o inmueble.',b:'Se cause perjuicio a quien tiene la cosa en su poder o a un tercero.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.236 CP: la sustracción de cosa propia se castiga cuando se trate de mueble o inmueble (a) y cause perjuicio al poseedor o a un tercero (b).'}},
{n:36, q:'En el artículo 236 del Código Penal se castiga la sustracción de una cosa propia a quien la tenga legítimamente en su poder, siempre y cuando:', o:{a:'El valor de la cosa exceda de 400 euros.',b:'Se trate de cosas de primera necesidad o destinadas a una utilidad social.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Art.236 CP: la sustracción de cosa propia no requiere ningún umbral de valor mínimo ni que sean cosas de primera necesidad. Lo relevante es el perjuicio al poseedor legítimo.'}},
{n:37, q:'El delito de sustracción de cosa propia del artículo 236 del Código Penal se castiga con las penas respectivamente previstas en su mitad superior cuando:', o:{a:'Se utilice a menores de 16 años para la comisión del delito.',b:'Hubiese mediado violencia o intimidación.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'Art.236 CP no establece esas circunstancias agravantes de mitad superior; el art.236 simplemente castiga la sustracción de cosa propia con multa.'}},
{n:38, q:'En el delito de sustracción de cosa propia del artículo 236 del Código Penal se impone la pena de multa de 1 a 3 meses...', o:{a:'Cuando el valor de la cosa sustraída no exceda de 400 euros.',b:'Cuando mediare una relación de parentesco entre el culpable del hecho y la víctima.',c:'Cuando los hechos se hubieren realizado mediante engaño o abusando de una posición de reconocida confianza con la víctima.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Art.236 CP: se impone multa de 1 a 3 meses cuando el valor de la cosa propia sustraída no excede de 400 euros.'}},
{n:39, q:'De acuerdo con lo previsto en el artículo 237 del Código Penal, son reos del delito de robo los que, con ánimo de lucro...', o:{a:'Se apoderaren de cosas muebles ajenas, empleando fuerza en las cosas para acceder al lugar donde estas se encuentren.',b:'Se apoderaren de cosas muebles ajenas con violencia o intimidación en las personas.',c:'Se apoderaren de cosas muebles ajenas, empleando fuerza en las cosas para abandonar el lugar donde estas se encuentren.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.237 CP: es reo de robo quien con ánimo de lucro se apodera de cosas muebles ajenas empleando fuerza en las cosas (para acceder o abandonar el lugar) (a, c) o violencia/intimidación en las personas (b).'}},
{n:40, q:'El delito de robo con fuerza en las cosas previsto en el artículo 237 del Código Penal requiere:', o:{a:'Que la fuerza se realice sobre la cosa objeto de sustracción.',b:'Que la fuerza se lleve a cabo para acceder al lugar donde la cosa se encuentra.',c:'Que la fuerza se lleve a cabo para abandonar el lugar donde la cosa se encuentra.',d:'Las respuestas b y c son correctas.'}, correct:'d', why:{d:'Art.237 CP: la fuerza en el robo puede emplearse para acceder (b) o para abandonar (c) el lugar donde está la cosa. No es la fuerza sobre la cosa misma.'}},
{n:41, q:'De las siguientes conductas indique la que no constituye delito de robo.', o:{a:'Entrar en vivienda ajena forzando una de las puertas de entrada y apropiarse de varias joyas.',b:'Amenazar con un cuchillo a la víctima hasta conseguir la entrega de la pulsera.',c:'Apropiarse del reloj de oro que la víctima ha dejado en el bolsillo de su abrigo, mientras utilizaba unas instalaciones deportivas.',d:'Coger las llaves de la vivienda que han quedado olvidadas en un bar y con ellas abrir la vivienda de la víctima y apropiarse de un aparato de televisión.'}, correct:'c', why:{c:'La opción c es hurto (apoderamiento sin violencia, intimidación ni fuerza en las cosas), no robo. Las otras opciones implican fuerza en las cosas (a, d) o violencia/intimidación (b).'}},
{n:42, q:'Constituye delito de robo con fuerza en las cosas, cuando en la ejecución del hecho:', o:{a:'Se produce escalamiento.',b:'Se utiliza a menores de 16 años o personas con discapacidad necesitadas de especial protección.',c:'Se hace uso de medios violentos.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Art.238.1ª CP: el escalamiento es una de las formas de fuerza que convierte el apoderamiento en robo con fuerza en las cosas.'}},
{n:43, q:'Constituye delito de robo con fuerza en las cosas, cuando en la ejecución del hecho:', o:{a:'Se produce rompimiento de pared, techo o suelo.',b:'Se produce fractura de muebles u objetos cerrados o sellados.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.238.2ª y 3ª CP: el rompimiento de pared/techo/suelo (a) y la fractura de muebles u objetos cerrados (b) son formas de fuerza constitutivas de robo.'}},
{n:44, q:'Constituye delito de robo con fuerza en las cosas, cuando en la ejecución del hecho:', o:{a:'Se produce la inutilización de los sistemas de alarma.',b:'Se abusa de las circunstancias personales de la víctima.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.238.5ª CP: la inutilización de sistemas de alarma es una de las modalidades de fuerza constitutivas de robo.'}},
{n:45, q:'Constituye delito de robo con fuerza en las cosas, cuando en la ejecución del hecho:', o:{a:'Se producen perjuicios de especial consideración.',b:'Se coloca a la víctima o a su familia en grave situación económica.',c:'Se hace uso de llaves falsas.',d:'Todas las respuestas anteriores son correctas.'}, correct:'c', why:{c:'Art.238.4ª CP: el uso de llaves falsas es una de las formas de fuerza constitutivas de robo.'}},
{n:46, q:'Indique cuál de las siguientes conductas no constituye delito de robo:', o:{a:'Javier, utilizando una varilla metálica, abre un vehículo ajeno y se apropia de una cazadora que había en su interior valorada en 300 euros.',b:'Anastasio se apropia de un maletín que contiene 15.000 euros aprovechando un descuido de su legítimo propietario.',c:'Irene golpea por detrás a Erika y le arrebata una cadena de oro que lleva en el cuello, valorada en 150 euros.',d:'Carlos, exhibiendo una jeringuilla usada y con gesto amenazante, consigue que Maribel le entregue su bolso que no contiene ningún objeto de valor.'}, correct:'b', why:{b:'La opción b es hurto (apoderamiento sin fuerza ni violencia/intimidación). Las demás son robo: a) fuerza en las cosas (varilla), c) violencia en las personas (golpe), d) intimidación (jeringuilla).'}},
{n:47, q:'Indique cuál de las siguientes conductas no constituye delito de robo.', o:{a:'Abel se coloca un pasamontañas y con un destornillador de grandes dimensiones amenaza al empleado de una gasolinera hasta conseguir que le entregue la recaudación.',b:'Renato se encuentra unas llaves en el ambulatorio. Con paciencia va probando si encajan en la cerradura de alguna de las viviendas de los alrededores hasta que consigue abrir la puerta de una de ellas, penetrando en la misma y apropiándose de 250 euros.',c:'Lucas llama a la puerta de una vivienda ajena y solicita que le den un vaso de agua. Aprovechando que la moradora acude a llenar el vaso, Lucas se introduce en una habitación y se apropia de varias joyas valoradas en 500 euros.',d:'Valentín espera hasta que observa desprevenida a una señora y, acercándose por detrás, le arrebata el bolso que lleva mediante un fuerte tirón. El bolso contiene efectos valorados en 450 euros.'}, correct:'c', why:{c:'La conducta de Lucas es un hurto con "engaño" pero no hay fuerza en las cosas ni violencia o intimidación; entra mediante estratagema pero no aplica fuerza técnica del art.238 CP. Las demás: a) intimidación, b) llaves falsas (fuerza), d) tirón con violencia.'}},
{n:48, q:'A efectos del delito de robo con fuerza en las cosas, se consideran llaves falsas:', o:{a:'Las ganzúas.',b:'Las llaves legítimas perdidas por el propietario.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.239 CP: son llaves falsas las ganzúas (a) y las llaves legítimas que han sido perdidas por el propietario (b).'}},
{n:49, q:'El art.239 del Código Penal considera llaves falsas:', o:{a:'Las ganzúas y otros instrumentos análogos.',b:'Las llaves legítimas perdidas por el propietario u obtenidas por un medio que constituya infracción penal.',c:'Cualesquiera que no sean destinadas por el propietario para abrir la cerradura violentada por el reo.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.239 CP: son llaves falsas las ganzúas y análogos (a), las legítimas perdidas u obtenidas ilegalmente (b) y cualquiera no destinada por el propietario para abrir esa cerradura (c).'}},
{n:50, q:'Santos, utilizando un mando a distancia de su propiedad consigue abrir el coche de otra persona, apropiándose de varios objetos valorados en 150 euros. La conducta de Santos:', o:{a:'Es constitutiva de un delito de robo con intimidación.',b:'Es constitutiva de un delito de robo con fuerza en las cosas.',c:'Es constitutiva de un delito de hurto.',d:'No es constitutiva de infracción penal alguna.'}, correct:'b', why:{b:'Art.239 CP: un mando a distancia usado para abrir un vehículo ajeno es un "instrumento tecnológico eficaz para la apertura de cerraduras" que se considera llave falsa, por lo que es robo con fuerza.'}},
{n:51, q:'A efectos del delito de robo con fuerza en las cosas, y de acuerdo con el contenido del artículo 239 del Código Penal, se consideran llaves:', o:{a:'Las tarjetas magnéticas o perforadas.',b:'Los mandos o instrumentos de apertura a distancia.',c:'Cualquier instrumento tecnológico eficaz para la apertura de cerraduras.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.239 CP: son llaves (y por tanto llaves falsas si se usan sin autorización) las tarjetas magnéticas (a), los mandos de apertura a distancia (b) y cualquier instrumento tecnológico eficaz (c).'}},
{n:52, q:'El tipo básico del delito de robo con fuerza en las cosas se castiga...', o:{a:'Con prisión de 1 a 4 años.',b:'Con prisión de 1 a 3 años.',c:'Con prisión de 2 a 5 años.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.240.1 CP: el robo con fuerza en las cosas se castiga en su tipo básico con prisión de 1 a 3 años.'}},
{n:53, q:'En los delitos de robo con fuerza en las cosas se impone la pena de prisión de 2 a 5 años:', o:{a:'Cuando el delito se cometa en casa habitada.',b:'Cuando se utilice a menores de 16 años para cometer el delito.',c:'Las respuestas a y b son incorrectas.',d:'Las respuestas a y b son correctas.'}, correct:'d', why:{d:'Art.241.1 CP: el robo con fuerza en casa habitada (a) y con empleo de menores de 16 años (b) se castigan con prisión de 2 a 5 años.'}},
{n:54, q:'En los delitos de robo con fuerza en las cosas se impone la pena de prisión de 2 a 5 años:', o:{a:'Cuando el delito reviste especial gravedad, atendiendo al valor de los efectos sustraídos.',b:'Cuando se sustraigan cosas de valor histórico.',c:'Cuando el delito se cometa en edificio o local abierto al público.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.241.1 CP: especial gravedad por valor (a), cosas de valor histórico (b) y edificio o local abierto al público (c) son agravantes del robo con fuerza.'}},
{n:55, q:'En los delitos de robo con fuerza en las cosas se impone la pena de prisión de 2 a 5 años:', o:{a:'Cuando se sustraigan cosas de valor artístico, histórico, cultural o científico.',b:'Cuando se produjeren perjuicios de especial consideración.',c:'Cuando se realice el hecho abusando de las circunstancias personales de la víctima.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.241.1 CP: todas esas circunstancias agravan el robo con fuerza a 2-5 años de prisión.'}},
{n:56, q:'En los delitos de robo con fuerza en las cosas se impone la pena de prisión de 2 a 5 años:', o:{a:'Cuando el robo se cometa con escalamiento.',b:'Cuando se sustraigan cosas de primera necesidad y se cause una situación de desabastecimiento.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.241.1 CP: escalamiento (a) y desabastecimiento por sustracción de cosas de primera necesidad (b) agravan el robo con fuerza.'}},
{n:57, q:'En los delitos de robo con fuerza en las cosas se impone la pena de prisión de 2 a 5 años:', o:{a:'Cuando se trate de productos agrarios o ganaderos o de los instrumentos o medios que se utilizan para su obtención, siempre que el delito se cometa en explotaciones agrícolas o ganaderas y se cause un perjuicio grave a las mismas.',b:'Cuando se inutilicen los sistemas específicos de alarma o guarda.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.241.1 CP: robo en explotaciones agrarias (a) y robo con inutilización de sistemas de alarma (b) son agravantes.'}},
{n:58, q:'En los delitos de robo con fuerza en las cosas se impone la pena de prisión de 2 a 5 años:', o:{a:'Cuando se emplean llaves falsas.',b:'Cuando al delinquir el culpable hubiera sido condenado ejecutoriamente al menos por tres delitos de los comprendidos en el Título XIII del Libro II del Código Penal.',c:'Si el delito se hubiere cometido en establecimiento abierto al público o en cualquiera de sus dependencias, fuera de las horas de apertura.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.241.1 CP: llaves falsas (a), reiteración delictiva (b) y robo en establecimiento fuera de horario (c) son agravantes.'}},
{n:59, q:'En los delitos de robo con fuerza en las cosas se impone la pena de prisión de 1 a 5 años:', o:{a:'Cuando se trate de conducciones, cableado, equipos o componentes de infraestructuras de suministro eléctrico, de hidrocarburos o de servicios de telecomunicaciones y se cause un quebranto grave a los mismos.',b:'Cuando el delito se hubiere cometido en establecimiento abierto al público o en cualquiera de sus dependencias, fuera de las horas de apertura.',c:'Cuando el delito tenga lugar en casa habitada o en cualquiera de sus dependencias.',d:'Las respuestas b y c son correctas.'}, correct:'a', why:{a:'Art.241.2 CP: el robo de infraestructuras de suministro eléctrico, hidrocarburos o telecomunicaciones causando quebranto grave se castiga con prisión de 1 a 5 años.'}},
{n:60, q:'Colocar a la víctima o a su familia en grave situación económica es una circunstancia que agrava:', o:{a:'El delito de robo con fuerza en las cosas del artículo 238 del Código Penal.',b:'El delito de hurto del artículo 234 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.235.1.5ª CP: poner a la víctima en grave situación económica es agravante del hurto (art.235). No está expresamente prevista para el robo con fuerza del mismo modo.'}},
{n:61, q:'De acuerdo con lo establecido en el art.237 del Código Penal, son reos de robo los que, con ánimo de lucro, se apoderaren de las cosas muebles ajenas:', o:{a:'Empleando violencia o intimidación en las personas al cometer el delito.',b:'Empleando violencia o intimidación en las personas para proteger la huida.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.237 CP: hay robo con violencia tanto cuando se emplea al cometer el delito (a) como para proteger la huida (b).'}},
{n:62, q:'De acuerdo con lo establecido en el art.237 del Código Penal, son reos de robo los que, con ánimo de lucro, se apoderaren de las cosas muebles ajenas:', o:{a:'Empleando violencia o intimidación sobre las personas que acudiesen en auxilio de la víctima.',b:'Empleando violencia o intimidación sobre los que le persiguieren.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.237 CP: también hay robo cuando la violencia/intimidación se dirige a quienes auxilian a la víctima (a) o persiguen al delincuente (b).'}},
{n:63, q:'A los efectos del delito de robo, el Código Penal considera casa habitada:', o:{a:'Todo albergue que constituya morada de una o varias personas, siempre que se encuentren en ella cuando se produzca el robo.',b:'Todo albergue que constituya morada de una o varias personas, aunque accidentalmente se encuentren ausentes de ella cuando el robo tenga lugar.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.241.3 CP: casa habitada es todo albergue que constituye morada de una o varias personas, aunque estén accidentalmente ausentes cuando se produzca el robo.'}},
{n:64, q:'A los efectos del delito de robo, el Código Penal considera dependencias de casa habitada o de edificio o local abiertos al público:', o:{a:'Sus patios y garajes, siempre que formen parte de la misma vivienda y estén accesibles y utilizables.',b:'Sus patios, garajes y demás departamentos o sitios cercados y contiguos al edificio, siempre que formen parte de la misma vivienda y sean utilizados para la vida en familia.',c:'Sus patios, garajes y demás departamentos o sitios cercados y contiguos al edificio y en comunicación interior con él, y con el cual formen una unidad física.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'c', why:{c:'Art.241.3 CP: son dependencias los patios, garajes y departamentos contiguos al edificio en comunicación interior con él, formando una unidad física.'}},
{n:65, q:'El delito de robo con fuerza en las cosas se castiga con la pena de 2 a 6 años de prisión, cuando...', o:{a:'Se cometa en casa habitada, edificio o local abierto al público o en cualquiera de sus dependencias y los hechos revistan especial gravedad, atendiendo a la forma de comisión del delito o a los perjuicios ocasionados.',b:'Se sustraigan cosas de valor artístico, histórico, cultural o científico.',c:'El culpable o culpables participen en los hechos como miembros de una organización o grupo criminal que se dedicare a la comisión de delitos comprendidos en el Título XIII del Libro II del Código Penal.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.241.1 CP in fine: en casa habitada con especial gravedad (a), bienes culturales (b) u organización criminal (c) la pena se eleva a 2-6 años.'}},
{n:66, q:'El delito de robo con fuerza en las cosas se castiga con la pena de 2 a 6 años de prisión cuando se cometa en casa habitada, edificio o local abierto al público, o en cualquiera de sus dependencias ...', o:{a:'Con fractura de puerta o ventana.',b:'Inutilizando los sistemas específicos de alarma o guarda.',c:'Utilizando menores de 16 años para la comisión del delito.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.241.1 CP: fractura (a), inutilización de alarmas (b) y uso de menores (c) en inmuebles son agravantes especiales que elevan la pena a 2-6 años.'}},
{n:67, q:'El delito de robo con violencia o intimidación en las personas está tipificado...', o:{a:'En el artículo 235 del Código Penal.',b:'En el artículo 238 del Código Penal.',c:'En el artículo 240 del Código Penal.',d:'En el artículo 242 del Código Penal.'}, correct:'d', why:{d:'El delito de robo con violencia o intimidación en las personas está tipificado en el artículo 242 del CP.'}},
{n:68, q:'El delito de robo con violencia o intimidación en las personas, previsto y penado en el artículo 242.1 del Código Penal, se castiga con:', o:{a:'Pena de prisión de 2 a 5 años, sin perjuicio de las penas que pudieran corresponder por los actos de violencia física realizados.',b:'Pena de prisión de 1 a 4 años, sin perjuicio de las penas que pudieran corresponder por los actos de violencia física realizados.',c:'Pena de prisión de 2 a 4 años, sin perjuicio de las penas que pudieran corresponder por los actos de violencia física realizados.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.242.1 CP: el robo con violencia o intimidación se castiga con prisión de 2 a 5 años, sin perjuicio de las penas por los actos de violencia realizados.'}},
{n:69, q:'Las penas previstas para el delito de robo con violencia o intimidación en las personas en el artículo 242 del Código Penal se impondrán en su mitad superior:', o:{a:'Cuando el delito se cometa en casa habitada, o en edificio o local abiertos al público o en cualquiera de sus dependencias.',b:'Cuando el robo revista especial gravedad, atendiendo al valor de los efectos sustraídos.',c:'Cuando el delincuente atacare a los que acudieren en auxilio de la víctima.',d:'Cuando se utilicen a menores de 16 años para cometer el delito.'}, correct:'d', why:{d:'Art.242.2 CP: se impone la pena en su mitad superior cuando se utilizan menores de 16 años, entre otras circunstancias.'}},
{n:70, q:'De acuerdo con lo previsto en el artículo 242 del Código Penal, el delito de robo con violencia o intimidación en las personas se castiga con la pena de prisión de 3 años y 6 meses a 5 años:', o:{a:'Cuando el delito se cometa en casa habitada, en cualquiera de sus dependencias.',b:'Cuando el robo revista especial gravedad, atendiendo al valor de los efectos sustraídos.',c:'Cuando el delincuente atacare a los que acudieren en auxilio de la víctima.',d:'Cuando se utilicen a menores de 16 años para cometer el delito.'}, correct:'a', why:{a:'Art.242.2 CP: cuando el robo con violencia se comete en casa habitada, la pena es de 3 años y 6 meses a 5 años (mitad superior de 2-5 años).'}},
{n:71, q:'Respecto a las penas previstas para el delito de robo con violencia o intimidación, el artículo 242.3 del Código Penal establece que se impondrán en su mitad superior:', o:{a:'Cuando el delito se cometa en casa habitada, o en edificio o local abiertos al público o en cualquiera de sus dependencias.',b:'Cuando se trate de cosas destinadas a un servicio público, siempre que la sustracción ocasionare un grave quebranto a éste o a una situación de desabastecimiento.',c:'Cuando el delincuente hiciere uso de armas u otros medios igualmente peligrosos al cometer el delito.',d:'Cuando se inutilicen los sistemas específicos de alarma o guarda.'}, correct:'c', why:{c:'Art.242.3 CP: la pena se impone en su mitad superior cuando el delincuente hace uso de armas u otros medios igualmente peligrosos.'}},
{n:72, q:'Respecto a las penas previstas para el delito de robo con violencia o intimidación, el artículo 242.3 del Código Penal establece que se impondrán en su mitad superior:', o:{a:'Cuando el delincuente hiciere uso de armas u otros medios igualmente peligrosos para proteger la huida.',b:'Cuando el robo se cometa en local abierto al público o en cualquiera de sus dependencias.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.242.3 CP: la pena también se impone en su mitad superior cuando el autor usa armas para proteger la huida.'}},
{n:73, q:'Al culpable de robo con violencia o intimidación en las personas, se le podrá imponer la pena inferior en grado a la prevista para este tipo delictivo:', o:{a:'Atendiendo a la menor entidad de la violencia o intimidación ejercidas y valorando además las restantes circunstancias del hecho.',b:'Cuando desistiere de la ejecución ya iniciada, sin perjuicio de las penas que le correspondan por los actos ya realizados.',c:'Cuando fuere una persona especialmente vulnerable, o con discapacidad necesitada de especial protección.',d:'Todas las respuestas anteriores son correctas'}, correct:'a', why:{a:'Art.242.4 CP: se puede imponer la pena inferior en grado cuando la violencia o intimidación es de menor entidad, valorando las circunstancias del hecho.'}},
{n:74, q:'De conformidad con lo dispuesto en el artículo 269 del Código Penal, la proposición, la conspiración y la proposición para cometer delitos de robo, será castigada', o:{a:'Con la pena inferior en grado a la del delito correspondiente.',b:'Con la pena inferior en dos grados a la del delito correspondiente.',c:'Con la pena inferior en uno o dos grados a la del delito correspondiente.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.269 CP: la proposición, conspiración y provocación para el robo se castigan con la pena inferior en uno o dos grados.'}},
{n:75, q:'De conformidad con lo dispuesto en el artículo 268 del Código Penal, los cónyuges que no estuvieren separados legalmente o de hecho o en proceso judicial de separación, divorcio o nulidad de su matrimonio, están exentos de responsabilidad criminal y sujetos únicamente a la civil...', o:{a:'En todos aquellos delitos patrimoniales de los artículos 234 a 267 CP, que se causaren entre sí.',b:'En los delitos contra la integridad moral que se causaren entre sí.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.268 CP: los cónyuges no separados están exentos de responsabilidad criminal (solo civil) en los delitos patrimoniales de los arts.234 a 267 CP que se causen entre sí.'}},
{n:76, q:'La excusa absolutoria del artículo 268 del Código Penal, es aplicable a...', o:{a:'Ascendientes y descendientes.',b:'Afines de hasta segundo grado, si viviesen juntos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.268 CP: la excusa absolutoria se extiende también a ascendientes/descendientes (a) y afines hasta segundo grado si conviven (b).'}},
{n:77, q:'Para que pueda ser aplicada la excusa absolutoria del artículo 268 del Código Penal, se requiere...', o:{a:'Que no concurra violencia ni intimidación.',b:'Que no se abuse de la vulnerabilidad de la víctima.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.268 CP: la excusa absolutoria no se aplica cuando concurre violencia o intimidación (a) ni cuando se abusa de la vulnerabilidad de la víctima (b).'}},
{n:78, q:'El delito de extorsión...', o:{a:'Está regulado en el artículo 244 del Código Penal.',b:'Está regulado en el capítulo IV, del Título XIII, del Libro II del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'d', why:{d:'La extorsión está en el artículo 243 del CP (no 244) y en el Capítulo III del Título XIII (no Capítulo IV), por lo que ambas opciones son incorrectas.'}},
{n:79, q:'Con respecto al delito de extorsión del artículo 243 del Código Penal, indique la respuesta incorrecta:', o:{a:'Para que exista delito debe concurrir ánimo de lucro.',b:'Para que exista delito los hechos deben realizarse con violencia o intimidación.',c:'La conducta consiste en obligar a otro a realizar u omitir un acto o negocio jurídico en perjuicio de su patrimonio o del de un tercero.',d:'Este delito se castiga con la pena de prisión de 2 a 5 años, sin perjuicio de las que pudieran imponerse por los actos de violencia física realizados.'}, correct:'a', why:{a:'La opción a es incorrecta: el art.243 CP no exige ánimo de lucro; lo que se requiere es el perjuicio patrimonial de la víctima, pero el fin del autor puede ser otro distinto del lucro.'}},
{n:80, q:'Con respecto al delito de extorsión del artículo 243 del Código Penal, indique la respuesta correcta:', o:{a:'Cuando se hiciere uso de armas u otros instrumentos peligrosos se impondrán las penas respectivamente previstas en su mitad superior.',b:'En atención a la gravedad de la violencia ejercidos, podrá imponerse la pena superior en grado a la respectivamente prevista en cada caso.',c:'Las penas a imponer por este delito son las de prisión de 1 a 5 años, sin perjuicio de las penas que pudieran imponerse por los actos de violencia física realizados.',d:'Debe concurrir perjuicio para el patrimonio del extorsionado, de un tercero, o de afectar de manera grave al interés público.'}, correct:'d', why:{d:'Art.243 CP: la extorsión requiere que se cause perjuicio patrimonial al extorsionado, a un tercero, o afectar gravemente al interés público.'}},
{n:81, q:'Los delitos de robo y hurto de uso de vehículos...', o:{a:'Están regulados en el artículo 244 del Código Penal.',b:'Están regulados en el capítulo IV, del Título XIII, del Libro II del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Los delitos de robo y hurto de uso de vehículos están regulados en el artículo 244 CP (a) y en el Capítulo IV del Título XIII (b).'}},
{n:82, q:'En el artículo 244 del Código Penal se castiga:', o:{a:'La sustracción de un vehículo a motor ajeno, sin ánimo de apropiárselo.',b:'La sustracción de cualquier vehículo ajeno, sin ánimo de apropiárselo.',c:'La utilización de cualquier vehículo ajeno, sin ánimo de apropiárselo.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'b', why:{b:'Art.244.1 CP: se castiga la sustracción de cualquier vehículo ajeno (no solo motor) sin ánimo de apropiárselo.'}},
{n:83, q:'En el artículo 244 del Código Penal se castiga:', o:{a:'La utilización de cualquier vehículo ajeno, sin ánimo de apropiárselo.',b:'La utilización de cualquier vehículo a motor ajeno, sin ánimo de apropiárselo.',c:'La sustracción o utilización de cualquier vehículo, sin ánimo de apropiárselo.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.244.1 CP: se castiga tanto la sustracción como la utilización de cualquier vehículo ajeno sin ánimo de apropiárselo.'}},
{n:84, q:'Con respecto al delito de robo/hurto de uso de vehículos del artículo 244 del Código Penal, indique la respuesta incorrecta:', o:{a:'Se castiga tanto la sustracción como la utilización de cualquier vehículo de motor o ciclomotor ajeno.',b:'Se requiere que la utilización del vehículo se realice sin la debida autorización.',c:'Para aplicar las penas previstas en su apartado 1, la restitución del vehículo debe realizarse de manera directa y en un plazo no superior a 48 horas.',d:'Todas las respuestas anteriores son incorrectas.'}, correct:'a', why:{a:'La opción a es incorrecta: el art.244 CP no limita el delito a vehículos de motor o ciclomotores; incluye cualquier vehículo ajeno.'}},
{n:85, q:'El que sustrajere un vehículo a motor o ciclomotor ajenos, sin ánimo de apropiárselo, será castigado con la pena de trabajos en beneficio de la comunidad de 31 a 90 días o multa de 2 a 12 meses:', o:{a:'Cierto, si lo restituyere, directa o indirectamente, en un plazo no superior a 48 horas.',b:'Cierto y también se castiga con la misma pena a quien lo utilizare sin la debida autorización.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.244.1 CP: TBC 31-90 días o multa 2-12 meses si se restituye en 48 horas (a), y la misma pena para quien lo usa sin autorización (b).'}},
{n:86, q:'De acuerdo con lo establecido en el art.244 del Código Penal, respecto del robo y hurto de uso de vehículos, si el hecho se cometiere con violencia o intimidación en las personas...', o:{a:'Se impondrá la pena superior en grado.',b:'Se impondrá la pena en su mitad superior.',c:'Se impondrán las penas previstas en el artículo 242 del Código Penal.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.244.3 CP: si el robo/hurto de uso se comete con violencia o intimidación, se aplican las penas del art.242 CP (robo con violencia).'}},
{n:87, q:'Cuando en la ejecución del delito de robo de uso de vehículos del artículo 244 del Código Penal se emplea fuerza en las cosas:', o:{a:'Se impone la pena superior en grado.',b:'Se impone la pena prevista en su mitad superior.',c:'Se castiga con las penas de trabajos en beneficio de la comunidad de 31 a 90 días y multa 6 a 12 meses.',d:'Se castiga en todo caso con las penas del artículo 242 del Código Penal.'}, correct:'b', why:{b:'Art.244.2 CP: si se emplea fuerza en las cosas en el robo/hurto de uso, se impone la pena del art.244.1 en su mitad superior.'}},
{n:88, q:'De acuerdo con lo previsto en el artículo 244 del Código Penal, en los casos de hurto/robo de uso de vehículos, si no se efectúa la restitución del vehículo en el plazo de 48 horas:', o:{a:'Se impone la pena superior en grado.',b:'Se impone la pena prevista en su mitad superior.',c:'Se castiga el hecho como robo o hurto en sus respectivos casos.',d:'Se castiga en todo caso con las penas del artículo 242 del Código Penal.'}, correct:'c', why:{c:'Art.244.4 CP: si no se restituye el vehículo en 48 horas, el hecho se castiga como robo o hurto en sus respectivos casos (con ánimo de apropiación).'}},
{n:89, q:'Los delitos de daños...', o:{a:'Están regulados en el capítulo X, del Título XIII, del Libro II del Código Penal (arts. 263 a 267).',b:'Están regulados en el capítulo XI, del Título XIII, del Libro II del Código Penal (arts. 264 a 269).',c:'Están regulados en el capítulo IX, del Título XIII, del Libro II del Código Penal (arts. 263 a 267).',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Los delitos de daños están en el Capítulo IX del Título XIII del Libro II (arts.263 a 267 del CP).'}},
{n:90, q:'Según el artículo 263.1 del Código Penal, causar daños en propiedad ajena se castiga con multa de 6 a 24 meses...', o:{a:'Siempre que dichos daños no estén comprendidos en otros títulos de este Código.',b:'Atendidas la condición económica de la víctima y la cuantía del daño.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.263.1 CP: los daños en propiedad ajena se castigan con multa de 6 a 24 meses, siempre que no estén en otros títulos (a) y atendiendo a la condición económica y cuantía (b).'}},
{n:91, q:'En el delito de daños del artículo 263.1 del Código Penal, se impone la pena de multa de 1 a 3 meses cuando...', o:{a:'Mediare imprudencia grave.',b:'La cuantía del daño causado no exceda de 400 euros.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.263.2 CP: se impone multa de 1 a 3 meses cuando la cuantía del daño no excede de 400 euros.'}},
{n:92, q:'El delito de daños del artículo 263.1 del Código Penal, se castiga con la pena de prisión de 1 a 3 años y multa de 12 a 24 meses, cuando...', o:{a:'El daño afecte a bienes comunales.',b:'Se hubiese cometido en el marco de una organización criminal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.263.2 CP: bienes comunales (a) y organización criminal (b) son circunstancias agravantes de los daños.'}},
{n:93, q:'El delito de daños del artículo 263.1 del Código Penal, se castiga con la pena de prisión de 1 a 3 años y multa de 12 a 24 meses, cuando...', o:{a:'El daño haya afectado a un número elevado de sistemas informáticos.',b:'El daño se haya cometido utilizando alguno de los medios a que se refiere el artículo 264 ter del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.263.2 CP: daños a sistemas informáticos masivos (a) y uso de herramientas del art.264 ter (b) son también circunstancias agravantes.'}},
{n:94, q:'El delito de daños del artículo 263.1 del Código Penal, se castiga con la pena de prisión de 1 a 3 años y multa de 12 a 24 meses, cuando...', o:{a:'Para la producción de los daños se empleen sustancias venenosas o corrosivas.',b:'Se arruine al perjudicado o se le coloque en grave situación económica.',c:'Se hayan ocasionado daños de especial gravedad.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.263.2 CP: sustancias venenosas (a), arruinar al perjudicado (b) y daños de especial gravedad (c) son agravantes de los daños.'}},
{n:95, q:'El delito de daños del artículo 263.1 del Código Penal, se castiga con la pena de prisión de 1 a 3 años y multa de 12 a 24 meses, cuando...', o:{a:'El daño se haya cometido por medio de incendio.',b:'El daño se realice para impedir el libre ejercicio de la autoridad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.263.2 CP: incendio (a) e impedir el ejercicio de la autoridad (b) son agravantes del delito de daños.'}},
{n:96, q:'El delito de daños del artículo 263.1 del Código Penal, se castiga con la pena de prisión de 1 a 3 años y multa de 12 a 24 meses, cuando...', o:{a:'El daño se cause en instalaciones o productos agrícolas o ganaderos.',b:'El daño se cause por medio de infección o contagio de ganado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.263.2 CP: daños en instalaciones agrícolas o ganaderas (a) y daños por infección de ganado (b) son agravantes.'}},
{n:97, q:'El delito de daños del artículo 263.1 del Código Penal, se castiga con la pena de prisión de 1 a 3 años y multa de 12 a 24 meses, cuando...', o:{a:'El daño se realice como consecuencia de las acciones ejecutadas en el ejercicio de las funciones de autoridad.',b:'Afecte a bienes de dominio o uso público.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.263.2 CP: daños realizados en ejercicio de funciones de autoridad (a) y a bienes de dominio público (b) son agravantes.'}},
{n:98, q:'El delito de daños del artículo 263.1 del Código Penal, se castiga con la pena de prisión de 1 a 3 años y multa de 12 a 24 meses, cuando...', o:{a:'El daño afecte a los intereses generales.',b:'Se cometa contra particulares que, como testigos o de cualquier otra manera, hayan contribuido o puedan contribuir a la ejecución o aplicación de las leyes o disposiciones generales.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.263.2 CP: daños a intereses generales (a) y a personas que contribuyen a la aplicación de leyes (b) son agravantes.'}},
{n:99, q:'Con respecto al delito de daños informáticos del artículo 264 del Código Penal, indique la respuesta que no es correcta.', o:{a:'Se castiga el hecho de borrar, dañar, deteriorar, alterar, suprimir o hacer inaccesibles datos informáticos o documentos electrónicos ajenos, cuando el resultado producido fuera grave.',b:'El sujeto activo solo puede ser autoridad o funcionario público.',c:'Para que exista delito la conducta punible debe realizarse sin autorización y de manera grave.',d:'Este delito se castiga con la pena de prisión de 6 meses a 3 años.'}, correct:'b', why:{b:'La opción b es incorrecta: el art.264 CP no limita el sujeto activo a autoridades o funcionarios; cualquier persona puede cometerlo.'}},
{n:100, q:'El delito de daños informáticos del artículo 264.1 del Código Penal se castiga con prisión de dos a cinco años, y multa del tanto al décuplo del perjuicio causado, cuando...', o:{a:'El hecho hubiera perjudicado gravemente el funcionamiento de servicios públicos esenciales.',b:'El hecho hubiera perjudicado gravemente la provisión de bienes de primera necesidad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.264.2 CP: agravan el delito informático cuando se perjudican gravemente los servicios públicos esenciales (a) o la provisión de bienes de primera necesidad (b).'}},
{n:101, q:'El delito de daños informáticos del artículo 264.1 del Código Penal se castiga con prisión de dos a cinco años, y multa del tanto al décuplo del perjuicio causado, cuando...', o:{a:'Los hechos hayan afectado al sistema informático de una infraestructura crítica.',b:'Se hubiese utilizado a menores para la comisión del delito.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.264.2 CP: afectar a una infraestructura crítica agrava el delito de daños informáticos.'}},
{n:102, q:'El delito de daños informáticos del artículo 264.1 del Código Penal se castiga con prisión de dos a cinco años, y multa del tanto al décuplo del perjuicio causado, cuando...', o:{a:'El delito se hubiese cometido en el marco de una organización criminal.',b:'Se hubiera creado una situación de peligro grave para la seguridad del Estado.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.264.2 CP: organización criminal (a) y peligro grave para la seguridad del Estado (b) son agravantes del delito informático.'}},
{n:103, q:'El delito de daños informáticos del artículo 264.1 del Código Penal se castiga con prisión de dos a cinco años, y multa del tanto al décuplo del perjuicio causado, cuando...', o:{a:'Cuando los hechos se hubiesen llevado a cabo con simulación de identidad.',b:'Cuando el autor de los hechos actúe bajo la dirección de cualquier potencia extranjera.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.264.2 CP: simulación de identidad (a) y actuación bajo dirección de potencia extranjera (b) son agravantes del delito informático.'}},
{n:104, q:'El delito de daños informáticos del artículo 264.1 del Código Penal se castiga con prisión de dos a cinco años, y multa del tanto al décuplo del perjuicio causado, cuando...', o:{a:'Cuando haya ocasionado daños de extrema gravedad.',b:'Cuando haya afectado a un número elevado de sistemas informáticos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.264.2 CP: daños de extrema gravedad (a) y afectación masiva de sistemas (b) son agravantes del delito informático.'}},
{n:105, q:'El delito de daños informáticos del artículo 264.1 del Código Penal se castiga con prisión de dos a cinco años, y multa del tanto al décuplo del perjuicio causado, cuando...', o:{a:'Cuando se hubiera creado una situación de peligro grave para la seguridad de la Unión Europea o de un Estado miembro de la Unión Europea.',b:'El delito se haya cometido por alguno de los medios a que se refiere el artículo 264 ter del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.264.2 CP: peligro para la seguridad de la UE o Estado miembro (a) y uso de herramientas del art.264 ter (b) son agravantes.'}},
{n:106, q:'El delito de daños informáticos del artículo 264.1 del Código Penal se castiga con prisión de dos a cinco años, y multa del tanto al décuplo del perjuicio causado, cuando...', o:{a:'Cuando los hechos se hubieran cometido mediante la utilización ilícita de datos personales de otra persona para facilitarse el acceso al sistema informático o para ganarse la confianza de un tercero.',b:'Haya ocasionado daños de especial gravedad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'a', why:{a:'Art.264.2 CP: el uso ilícito de datos personales de otra persona para acceder al sistema es una circunstancia agravante específica.'}},
{n:107, q:'Los delitos de daños informáticos del artículo 264.2 del Código Penal podrán castigarse con la pena superior en grado, cuando...', o:{a:'Los hechos se hubieran cometido mediante la utilización ilícita de datos personales de otra persona para facilitarse el acceso al sistema informático o para ganarse la confianza de un tercero.',b:'Hubieran resultado daños de extrema gravedad.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.264.3 CP: la pena puede ser superior en grado cuando hay uso ilícito de datos personales (a) o daños de extrema gravedad (b).'}},
{n:108, q:'Cuando los delitos de daños informáticos del artículo 264 del Código Penal se hubieran cometido mediante la utilización ilícita de datos personales de otra persona, para facilitarse el acceso al sistema informático, o para ganarse la confianza de un tercero, podrán castigarse con...', o:{a:'Las penas previstas en los respectivos casos, en su mitad superior.',b:'Las penas superiores en grado a las previstas en los respectivos casos.',c:'Las penas superiores en uno o dos grados a las previstas en los respectivos casos.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'a', why:{a:'Art.264.3 CP: el uso ilícito de datos personales en los delitos de daños informáticos permite castigar con las penas en su mitad superior.'}},
{n:109, q:'En el artículo 264 bis del Código Penal se castiga al que, sin estar autorizado y de manera grave, obstaculizara o interrumpiera el funcionamiento de un sistema informático ajeno...', o:{a:'Realizando alguna de las conductas previstas en el artículo 264 CP.',b:'Con la intención de conseguir un beneficio económico para sí mismo o para un tercero.',c:'Las respuestas a y b son correctas.',d:'Las respuesta a y b son incorrectas.'}, correct:'c', why:{c:'Art.264 bis CP: la obstaculización de sistemas informáticos se comete realizando conductas del art.264 (a) con intención de obtener beneficio económico (b).'}},
{n:110, q:'En el artículo 264 bis del Código Penal se castiga al que, sin estar autorizado y de manera grave, obstaculizara o interrumpiera el funcionamiento de un sistema informático ajeno...', o:{a:'Introduciendo o transmitiendo datos.',b:'Destruyendo, dañando, inutilizando eliminando o sustituyendo un sistema informático telemático de almacenamiento de información electrónica.',c:'Las respuestas a y b son correctas.',d:'Las respuesta a y b son incorrectas.'}, correct:'c', why:{c:'Art.264 bis CP: la obstaculización puede realizarse introduciendo/transmitiendo datos (a) o destruyendo/dañando sistemas de almacenamiento (b).'}},
{n:111, q:'Cuando el delito de daños informáticos del artículo 264 bis del Código Penal hubiera perjudicado de forma relevante la actividad normal de una empresa o negocio, o de una administración pública...', o:{a:'Se impondrán las penas previstas en su mitad superior.',b:'Se impondrá la pena superior en grado.',c:'Podrá imponerse la pena en su mitad superior, pudiéndose alcanzar la pena superior en grado.',d:'Se impondrá en su mitad superior, pudiéndose alcanzar la pena superior en grado.'}, correct:'c', why:{c:'Art.264 bis 2 CP: cuando el delito perjudica a una empresa, negocio o administración, la pena puede imponerse en su mitad superior, pudiendo alcanzar la superior en grado.'}},
{n:112, q:'El delito de daños informáticos del artículo 264 bis del Código Penal podrá castigarse con las penas de prisión de 3 a 8 años y multa del triplo al décuplo del perjuicio ocasionado cuando...', o:{a:'Se hubiese cometido el delito en el marco de una organización criminal.',b:'Se hubiere perjudicado gravemente el funcionamiento de servicios esenciales.',c:'Los hechos hayan afectado al sistema informático de una infraestructura crítica.',d:'Todas las respuestas anteriores son correctas.'}, correct:'d', why:{d:'Art.264 bis 3 CP: organización criminal (a), perjuicio a servicios esenciales (b) e infraestructura crítica (c) son agravantes que pueden llevar a 3-8 años.'}},
{n:113, q:'En el artículo 264 ter del Código Penal se castiga al que, sin estar debidamente autorizado, produzca, adquiera para su uso, importe o, de cualquier modo, facilite a terceros, con la intención de facilitar la comisión de alguno de los delitos a que se refieren los artículos 264 y 264 bis...', o:{a:'Un programa informático, concebido o adaptado principalmente para cometer alguno de los delitos a que se refieren los dos artículos citados.',b:'una contraseña de ordenador, un código de acceso o datos similares que permitan acceder a la totalidad o a una parte de un sistema de información.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas'}, correct:'c', why:{c:'Art.264 ter CP: son instrumentos cuya producción/adquisición/facilitación se castiga tanto los programas maliciosos (a) como las contraseñas/códigos de acceso (b).'}},
{n:114, q:'Los delitos del artículo 264 ter del Código Penal se castigan con...', o:{a:'Prisión de seis meses a dos años y multa de tres a dieciocho meses.',b:'Prisión de seis meses a dos años o multa de tres a dieciocho meses.',c:'Prisión de seis meses a tres años o multa de tres a dieciocho meses.',d:'Prisión de seis meses a tres años y multa de tres a dieciocho meses.'}, correct:'b', why:{b:'Art.264 ter CP: los delitos de producción/facilitación de herramientas informáticas se castigan con prisión de 6 meses a 2 años O multa de 3 a 18 meses.'}},
{n:115, q:'Cuando de acuerdo con lo establecido en el artículo 31 bis del Código Penal, una persona jurídica sea responsable de los delitos de daños informáticos comprendidos en los artículos 264, 264 bis y 264 quater, se le impondrá la pena de...', o:{a:'Multa de dos a cinco años o del quíntuplo a doce veces el valor del perjuicio causado, si resulta una cantidad superior, cuando se trate de delitos castigados con una pena de prisión de más de tres años.',b:'Multa de uno a tres años o del triple a ocho veces el valor del perjuicio causado, si resulta una cantidad superior, cuando se trate de delitos castigados con una pena de prisión de tres años o menos.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.264 quater CP: la persona jurídica responde con multa de 2-5 años o quíntuplo-12 veces el perjuicio (>3 años de prisión) (a), y multa 1-3 años o triple-8 veces (≤3 años) (b).'}},
{n:116, q:'En un delito de daños tipificado en el artículo 265 del Código Penal...', o:{a:'Se castiga al que destruyere, dañare de modo grave, o inutilizare para el servicio, aun de forma temporal, obras, establecimientos o instalaciones militares, buques de guerra, aeronaves militares, medios de transporte o transmisión militar, material de guerra, aprovisionamiento u otros medios o recursos afectados al servicio de las Fuerzas Armadas o de las Fuerzas y Cuerpos de Seguridad.',b:'Para que tenga lugar este delito los daños causados deben ser superiores a 400 euros.',c:'Las penas a imponer son las de prisión de dos a cinco años.',d:'Todas las respuestas anteriores son correctas.'}, correct:'a', why:{a:'Art.265 CP: se castiga la destrucción o inutilización de instalaciones militares, buques, aeronaves, material de guerra u otros medios de las Fuerzas Armadas o FCS.'}},
{n:117, q:'Los daños previstos en el apartado 1 del artículo 263 del Código Penal...', o:{a:'Se castigan en el artículo 266.1 del Código Penal cuando se realicen mediante incendio, o provocando explosiones.',b:'Se castigan en el artículo 266.1 del Código Penal cuando se realicen poniendo en peligro la vida o integridad de las personas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.266.1 CP: los daños del art.263.1 se castigan de forma agravada en el art.266.1 cuando se realizan mediante incendio/explosión (a) o poniendo en peligro la vida (b).'}},
{n:118, q:'Los daños previstos en el apartado 1 del artículo 266 del Código Penal se castigan con...', o:{a:'Prisión de uno a tres años.',b:'Prisión de dos a cinco años.',c:'Prisión de uno a tres años y multa del tanto al triplo del valor del daño causado.',d:'Ninguna de las respuestas anteriores es correcta.'}, correct:'c', why:{c:'Art.266.1 CP: los daños causados mediante incendio/explosión o con peligro para la vida se castigan con prisión de 1 a 3 años y multa del tanto al triple del daño.'}},
{n:119, q:'El delito de daños por imprudencia...', o:{a:'Puede ser cometido por imprudencia grave o menos grave.',b:'Está regulado en el artículo 266.4 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.267 CP: el delito de daños por imprudencia está regulado en ese artículo y puede ser grave o menos grave (a). El art.266.4 regula una modalidad específica de daños (b).'}},
{n:120, q:'El delito de daños por imprudencia...', o:{a:'Requiere que la cuantía del daño causado sea superior a 50.000 euros.',b:'Requiere que la imprudencia sea grave.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.267 CP: los daños por imprudencia requieren imprudencia grave (b) y cuantía superior a 80.000 euros (no 50.000); pero el libro plantea 50.000 en la opción a, por lo que si ambas son correctas según el libro, se mantiene c.'}},
{n:121, q:'El delito de daños por imprudencia...', o:{a:'Requiere que la cuantía del daño causado sea superior a 80.000 euros.',b:'Se castiga en el artículo 267 del Código Penal.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.267 CP: los daños por imprudencia grave se castigan en el art.267 (b) y requieren que la cuantía supere los 80.000 euros (a).'}},
{n:122, q:'El delito de daños por imprudencia...', o:{a:'Se castiga con pena de prisión de 3 a 9 meses.',b:'Solo es perseguible previa denuncia de la persona agraviada, de su representante legal, o del Ministerio Fiscal cuando la víctima sea menor de edad, persona con discapacidad necesitada de especial protección o una persona desvalida.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'c', why:{c:'Art.267 CP: los daños por imprudencia se castigan con prisión de 3 a 9 meses (a) y solo son perseguibles mediante denuncia del agraviado, representante legal o MF en esos supuestos (b).'}},
{n:123, q:'En el delito de daños del artículo 267 del Código Penal...', o:{a:'El perdón de la persona ofendida extingue la acción penal.',b:'Cuando se comete por medio de incendio, veneno o explosivo, se imponen las penas superiores en grado a las respectivamente previstas.',c:'Las respuestas a y b son correctas.',d:'Las respuestas a y b son incorrectas.'}, correct:'b', why:{b:'Art.267 CP in fine: cuando los daños por imprudencia se causan mediante incendio, veneno o explosivo, se impone la pena superior en grado.'}},
];
